CREATE TABLE `Merchant` (`id` INT PRIMARY KEY, `name` VARCHAR(100), `money` DECIMAL(18,2), `apiKey` TEXT, `createdAt` DATETIME(3)) ENGINE=InnoDB;
CREATE TABLE `AdminSession` (`id` VARCHAR(64) PRIMARY KEY, `session` TEXT) ENGINE=InnoDB;
CREATE TABLE `MerchantInvoiceConfig` (`merchantId` INT PRIMARY KEY, `config` TEXT) ENGINE=InnoDB;
CREATE TABLE `MerchantBinding` (`id` VARCHAR(64) PRIMARY KEY, `merchantId` INT) ENGINE=InnoDB;
CREATE TABLE `PayType` (`id` INT PRIMARY KEY, `code` VARCHAR(30)) ENGINE=InnoDB;
CREATE TABLE `Channel` (`id` INT PRIMARY KEY, `config` JSON) ENGINE=InnoDB;
CREATE TABLE `Order` (`tradeNo` VARCHAR(64) PRIMARY KEY, `money` DECIMAL(18,2), `status` VARCHAR(20)) ENGINE=InnoDB;
CREATE TABLE `NotifyLog` (`id` INT PRIMARY KEY, `tradeNo` VARCHAR(64), `status` VARCHAR(20)) ENGINE=InnoDB;
CREATE TABLE `Invoice` (`id` VARCHAR(64) PRIMARY KEY, `tradeNo` VARCHAR(64), `amount` DECIMAL(18,2)) ENGINE=InnoDB;
CREATE TABLE `InvoiceApplication` (`id` VARCHAR(64) PRIMARY KEY, `tradeNo` VARCHAR(64)) ENGINE=InnoDB;
CREATE TABLE `Config` (`key` VARCHAR(64) PRIMARY KEY, `value` TEXT) ENGINE=InnoDB;
